head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.tmpUpDepNm = "";
scwin.tmpUpDepCd = "";
scwin.tmpDepNm = "";
scwin.tmpDepCd = "";
scwin.tmpChrgIndNm = "";
scwin.tmpDutyGrpTpCd = "";
scwin.tmpSndlocTpCd = "";
scwin.tmpKclicUsrTpId = "";
scwin.logicTp = "0"; // 0:신규, 1:수정, 2:삭제
scwin.isExistDepInfo = false;
scwin.usrPosition = 1; // 트랜젝션 후에 사용자리스트를 리로드 하고 선택 위치를 이동 시키기 위해
scwin.position = 1; // 사용자포지션
scwin.isSameDept = true;

///////// 2. 초기화 영역 /////////
/* ★Wcraft guide★    
스크립트 수작업 유의사항

*/
/**
 * @method
 * @name onpageload
 * @description 화면 로드 시 호출되는 진입점(현재 처리 로직 없음, 초기 조회는 gform_onload 참조).
 * @returns {void}
 * @hidden N
 * @example (body ev:onpageload 바인딩으로 자동 호출)
 */
scwin.onpageload = function() {
};

/**
 * @method
 * @name onpageunload
 * @description 화면 종료 시 호출되는 진입점(현재 처리 로직 없음).
 * @returns {void}
 * @hidden N
 * @example (body ev:onpageunload 바인딩으로 자동 호출)
 */
scwin.onpageunload = function() {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name imgDelDate_onclick
 * @description 달력 팝업(popUpCalendar)을 열어 시작/종료일(meAskDate)을 선택하도록 한다.
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 * @example scwin.imgDelDate_onclick(e);
 */
scwin.imgDelDate_onclick = function(e) {
    try {
        popUpCalendar(tboxAskDate, 'meAskDate', 'yyyymmdd');
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDMGT40020.imgDelDate_onclick" });
    }
};

/**
 * @method
 * @name mdsDepLst_OnLoadCompleted
 * @description 부서/팀 목록(mdsDepLst) 조회 완료 콜백 — 보관된 선택 위치(usrPosition)로 포커스 셀을 이동한다.
 * @param {Object} e 서브미션 응답 객체
 * @returns {void}
 * @hidden N
 * @example scwin.mdsDepLst_OnLoadCompleted(e);
 */
scwin.mdsDepLst_OnLoadCompleted = function(e) {
    try {
        mdsDepLst.setFocusedCell(scwin.usrPosition, 0);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDMGT40020.mdsDepLst_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name mgPdept_OnClick
 * @description 본부(급) 목록 그리드 클릭 시 해당 본부를 부서/팀 목록에서 찾아 포커스한다(schMyDept).
 * @param {Number} row 클릭한 행 인덱스
 * @param {String} colid 클릭한 컬럼 id
 * @returns {void}
 * @hidden N
 * @example scwin.mgPdept_OnClick(row, colid);
 */
scwin.mgPdept_OnClick = function(row, colid) {
    try {
        scwin.schMyDept(1, row);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDMGT40020.mgPdept_OnClick" });
    }
};

/**
 * @method
 * @name mgPdept_OnKeyPress
 * @description 본부(급) 목록 그리드에서 Enter(13) 입력 시 검색 입력(tbAuthSch)을 표시하고 포커스한다.
 * @param {String} keycode 입력된 키 코드
 * @returns {void}
 * @hidden N
 * @example scwin.mgPdept_OnKeyPress('13');
 */
scwin.mgPdept_OnKeyPress = function(keycode) {
    try {
        if (keycode === '13') {
            tbAuthSch.style.display = "";

            tbAuthSch.focus();
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDMGT40020.mgPdept_OnKeyPress" });
    }
};

/**
 * @method
 * @name mdsPdept_OnLoadCompleted
 * @description 본부(급) 목록(mdsPdept) 조회 완료 콜백(현재 처리 로직 없음).
 * @param {Object} e 서브미션 응답 객체
 * @returns {void}
 * @hidden N
 * @example scwin.mdsPdept_OnLoadCompleted(e);
 */
scwin.mdsPdept_OnLoadCompleted = function(e) {

};

/**
 * @method
 * @name btnNew_onclick
 * @description ①신규등록 버튼 — 동급/하위부서 등록 여부를 확인한 뒤 신규("0") 모드로 입력 영역을 세팅한다.
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 * @example scwin.btnNew_onclick(e);
 */
scwin.btnNew_onclick = function(e) {
    try {
        if (confirm("동급부서로 등록하려면 '예', 하위부서로 등록하려면 '취소'를 선택하세요.")) {
            scwin.isSameDept = true;
        } else {
            scwin.isSameDept = false;
        }
        scwin.setDeptInfo("0");
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDMGT40020.btnNew_onclick" });
    }
};

/**
 * @method
 * @name btnModify_onclick
 * @description ②수정 버튼 — 수정("1") 모드로 입력 영역을 세팅한다.
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 * @example scwin.btnModify_onclick(e);
 */
scwin.btnModify_onclick = function(e) {
    try {
        scwin.setDeptInfo("1");
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDMGT40020.btnModify_onclick" });
    }
};

/**
 * @method
 * @name btnDelete_onclick
 * @description ③삭제 버튼 — 삭제("2") 모드로 입력 영역을 세팅한다.
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 * @example scwin.btnDelete_onclick(e);
 */
scwin.btnDelete_onclick = function(e) {
    try {
        scwin.setDeptInfo("2");
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDMGT40020.btnDelete_onclick" });
    }
};

/**
 * @method
 * @name btnAddSave_onclick
 * @description ④저장 버튼 — 기능 선택·부서코드 필수값을 확인한 뒤 삭제 모드면 팀원 존재 여부 확인(checkMemberExist), 그 외에는 저장(doDepSave)을 수행한다.
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 * @example scwin.btnAddSave_onclick(e);
 */
scwin.btnAddSave_onclick = function(e) {
    try {
        const dep_cd = txtDeptCd.value;
        if (scwin.logicTp === '') {
            alert("①, ②, ③ 중 하나의 기능을 먼저 클릭해야 합니다.");
        }
        if (dep_cd === '') {
            alert("부서코드는 필수 입니다.");

            txtDeptCd.focus();
        } else {
            if (scwin.logicTp === '2') {
                scwin.checkMemberExist();
            } else {
                scwin.doDepSave();
            }
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDMGT40020.btnAddSave_onclick" });
    }
};

/**
 * @method
 * @name trSave_OnSuccess
 * @description 저장 트랜잭션(trSave) 성공 콜백 — 처리완료 알림 후 부서/팀 목록을 리셋한다.
 * @param {Object} e 트랜잭션 응답 객체
 * @returns {void}
 * @hidden N
 * @example scwin.trSave_OnSuccess(e);
 */
scwin.trSave_OnSuccess = function(e) {
    try {
        alert('처리완료');

        scwin.resetList();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDMGT40020.trSave_OnSuccess" });
    }
};

/**
 * @method
 * @name trSave_OnFail
 * @description 저장 트랜잭션(trSave) 실패 콜백 — 실패 알림을 표시한다.
 * @param {Object} e 트랜잭션 응답 객체
 * @returns {void}
 * @hidden N
 * @example scwin.trSave_OnFail(e);
 */
scwin.trSave_OnFail = function(e) {
    try {
        alert('trSave.OnFail()');
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDMGT40020.trSave_OnFail" });
    }
};

/**
 * @method
 * @name tbSch_onkeydown
 * @description 부서/팀 검색 입력에서 Enter(13) 입력 시 부서 검색(schDept)을 수행하고, 그 외 입력 시 검색 상태를 초기화한다.
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 * @example scwin.tbSch_onkeydown(e);
 */
scwin.tbSch_onkeydown = function(e) {
    try {
        if (Number(e.keyCode) === 13) {
            if (!scwin.isExistDepInfo) {
                scwin.position = 1;
            }
            scwin.schDept(tbSch.value);
        } else {
            positon = 1;
            scwin.isExistDepInfo = false;
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDMGT40020.tbSch_onkeydown" });
    }
};

/**
 * @method
 * @name txtDeptCd_onblur
 * @description 부서코드 입력 blur 시 담당업종명(txtChrgIndNm)에 부서코드 값을 설정한다.
 * @returns {void}
 * @hidden N
 * @example scwin.txtDeptCd_onblur();
 */
scwin.txtDeptCd_onblur = function() {
    try {
        txtChrgIndNm.setValue(txtDeptCd.value);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDMGT40020.txtDeptCd_onblur" });
    }
};

/**
 * @method
 * @name mdsDepHist_OnLoadCompleted
 * @description 부서/팀 히스토리(mdsDepHist) 조회 완료 콜백(현재 처리 로직 없음).
 * @param {Object} e 서브미션 응답 객체
 * @returns {void}
 * @hidden N
 * @example scwin.mdsDepHist_OnLoadCompleted(e);
 */
scwin.mdsDepHist_OnLoadCompleted = function(e) {

};

/**
 * @method
 * @name txtSrchDepHist_onkeydown
 * @description 히스토리 검색 입력에서 Enter(13) 입력 시 부서 히스토리 목록을 조회한다(getDepHistLst).
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 * @example scwin.txtSrchDepHist_onkeydown(e);
 */
scwin.txtSrchDepHist_onkeydown = function(e) {
    try {
        if (Number(e.keyCode) === 13) scwin.getDepHistLst(txtSrchDepHist.value);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDMGT40020.txtSrchDepHist_onkeydown" });
    }
};

/**
 * @method
 * @name mdsDepLst_OnRowPosChanged
 * @description 부서/팀 목록 행 위치 변경 시 선택 행의 부서 정보를 임시 변수(tmp*)에 보관하고 입력 영역을 초기화한다.
 * @param {Number} row 선택된 행 인덱스
 * @returns {void}
 * @hidden N
 * @example scwin.mdsDepLst_OnRowPosChanged(row);
 */
scwin.mdsDepLst_OnRowPosChanged = function(row) {
    try {
        scwin.tmpUpDepNm = mdsDepLst.getCellData(row, "UP_DEP_NM");
        scwin.tmpUpDepCd = mdsDepLst.getCellData(row, "UP_DEP_CD");
        scwin.tmpDepNm = mdsDepLst.getCellData(row, "DEP_NM");
        scwin.tmpDepCd = mdsDepLst.getCellData(row, "DEP_CD");
        scwin.tmpChrgIndNm = mdsDepLst.getCellData(row, "CHRG_IND_NM");
        scwin.tmpDutyGrpTpCd = mdsDepLst.getCellData(row, "DUTY_GRP_TP_CD");
        scwin.tmpSndlocTpCd = mdsDepLst.getCellData(row, "SNDLOC_TP_CD");
        scwin.tmpKclicUsrTpId = mdsDepLst.getCellData(row, "KCLIC_USR_TP_ID");
        scwin.clearEditTextBox();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDMGT40020.mdsDepLst_OnRowPosChanged" });
    }
};

/**
 * @method
 * @name img_1_onclick
 * @description 고침 버튼 — 부서/팀 목록(mdsDepLst)을 리셋한다.
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 * @example scwin.img_1_onclick(e);
 */
scwin.img_1_onclick = function(e) {
    try {
        mdsDepLst.reset();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDMGT40020.img_1_onclick" });
    }
};

/**
 * @method
 * @name btnHistSave_onclick
 * @description 히스토리 저장 버튼 — 수정/삭제된 히스토리를 저장한다(doHistSave).
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 * @example scwin.btnHistSave_onclick(e);
 */
scwin.btnHistSave_onclick = function(e) {
    try {
        scwin.doHistSave();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDMGT40020.btnHistSave_onclick" });
    }
};

/**
 * @method
 * @name mxmGusrLst_OnLButtonDown
 * @description 사용자 목록 클릭 시 선택 위치(usrPosition)를 보관하고 선택 부서의 히스토리 목록을 조회한다.
 * @param {String} type 버튼 다운 유형
 * @param {Number} row 클릭한 행 인덱스
 * @param {String} colid 클릭한 컬럼 id
 * @param {Number} x 마우스 X 좌표
 * @param {Number} y 마우스 Y 좌표
 * @returns {void}
 * @hidden N
 * @example scwin.mxmGusrLst_OnLButtonDown(type, row, colid, x, y);
 */
scwin.mxmGusrLst_OnLButtonDown = function(type, row, colid, x, y) {
    try {
        scwin.usrPosition = row;
        scwin.getDepHistLst(scwin.tmpDepCd);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDMGT40020.mxmGusrLst_OnLButtonDown" });
    }
};

/**
 * @method
 * @name mgDepHist_onlbuttondown
 * @description 부서/팀 히스토리 그리드 클릭 시 해당 부서를 부서/팀 목록에서 찾아 포커스한다(schMyDept).
 * @param {Number} rowIndex 클릭한 행 인덱스
 * @param {Number} columnIndex 클릭한 컬럼 인덱스
 * @param {String} columnId 클릭한 컬럼 id
 * @returns {void}
 * @hidden N
 * @example scwin.mgDepHist_onlbuttondown(rowIndex, columnIndex, columnId);
 */
scwin.mgDepHist_onlbuttondown = function(rowIndex, columnIndex, columnId) {
    try {
        scwin.schMyDept(2, row);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDMGT40020.mgDepHist_onlbuttondown" });
    }
};

/**
 * @method
 * @name txtUpDeptCd_onkeyup
 * @description 상위부서코드 4자리 입력 시 부서/팀 목록에서 해당 코드를 찾아 상위부서명(txtUpDeptNm)을 자동 설정한다.
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 * @example scwin.txtUpDeptCd_onkeyup(e);
 */
scwin.txtUpDeptCd_onkeyup = function(e) {
    try {
        const ver = txtUpDeptCd.value;
        let deptCd = '';
        if (ver.length === 4) {
            for (let i = 1; i <= mdsDepLst.getRowCount(); i++) {
                deptCd = mdsDepLst.getCellData(i, "DEP_CD");
                if (ver === deptCd) {
                    txtUpDeptNm.setValue(mdsDepLst.getCellData(i, "DEP_NM"));
                    break;
                }
            }
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDMGT40020.txtUpDeptCd_onkeyup" });
    }
};

/**
 * @method
 * @name mdsMemberCheck_OnLoadCompleted
 * @description 팀원 존재 여부(mdsMemberCheck) 조회 완료 콜백 — 팀원이 있으면 삭제 불가 알림, 없으면 저장(doDepSave)을 진행한다.
 * @param {Object} e 서브미션 응답 객체
 * @returns {void}
 * @hidden N
 * @example scwin.mdsMemberCheck_OnLoadCompleted(e);
 */
scwin.mdsMemberCheck_OnLoadCompleted = function(e) {
    try {
        let cnt = 0;
        if (rowcount !== 0) {
            cnt = mdsMemberCheck.getCellData(1, "COUNT");
            if (cnt !== 0) {
                alert("팀원이 있는 팀은 삭제 할 수 없습니다.");
            } else {
                scwin.doDepSave();
            }
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDMGT40020.mdsMemberCheck_OnLoadCompleted" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name getDataSetData
 * @description 본부(급) 목록(mdsPdept)·부서/팀 목록(mdsDepLst)을 순차 조회하고 구 콜백을 연결한다.
 * @returns {void}
 * @hidden N
 * @example await scwin.getDataSetData();
 */
scwin.getDataSetData = async function() {
    const sbmOptions = {
        id : "sbm_mdsPdept",
        action : "/depusr.do",
        ref : "",
        target : "mdsPdept=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    scwin.mdsPdept_OnLoadCompleted(sbmRtn); // 구 콜백 연결

    const sbmOptions2 = {
        id : "sbm_mdsDepLst",
        action : "/depusr.do",
        ref : "",
        target : "mdsDepLst=body.content",
        isProcessMsg : false
    };

    const sbmRtn2 = await $c.sbm.executeDynamic(sbmOptions2);
    scwin.mdsDepLst_OnLoadCompleted(sbmRtn2); // 구 콜백 연결

};

/**
 * @method
 * @name setDataSet
 * @description 화면 데이터셋(mdsDepLst·mdsPdept·mdsDeptSave·mdsDepHist·mdsMemberCheck) 초기 설정 서브미션을 순차 실행하고 구 콜백을 연결한다.
 * @returns {void}
 * @hidden N
 * @example await scwin.setDataSet();
 */
scwin.setDataSet = async function() {
    const sbmOptions = {
        id : "sbm_mdsDepLst",
        action : "/gauceSystemierAdaptor.do",
        ref : "",
        target : "mdsDepLst=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    scwin.mdsDepLst_OnLoadCompleted(sbmRtn); // 구 콜백 연결

    const sbmOptions2 = {
        id : "sbm_mdsPdept",
        action : "/gauceSystemierAdaptor.do",
        ref : "",
        target : "mdsPdept=body.content",
        isProcessMsg : false
    };

    const sbmRtn2 = await $c.sbm.executeDynamic(sbmOptions2);
    scwin.mdsPdept_OnLoadCompleted(sbmRtn2); // 구 콜백 연결

    const sbmOptions3 = {
        id : "sbm_mdsDeptSave",
        action : "/gauceSystemierAdaptor.do",
        ref : "",
        target : "mdsDeptSave=body.content",
        isProcessMsg : false
    };

    const sbmRtn3 = await $c.sbm.executeDynamic(sbmOptions3);

    const sbmOptions4 = {
        id : "sbm_mdsDepHist",
        action : "/gauceSystemierAdaptor.do",
        ref : "",
        target : "mdsDepHist=body.content",
        isProcessMsg : false
    };

    const sbmRtn4 = await $c.sbm.executeDynamic(sbmOptions4);
    scwin.mdsDepHist_OnLoadCompleted(sbmRtn4); // 구 콜백 연결

    const sbmOptions5 = {
        id : "sbm_mdsMemberCheck",
        action : "/gauceSystemierAdaptor.do",
        ref : "",
        target : "mdsMemberCheck=body.content",
        isProcessMsg : false
    };

    const sbmRtn5 = await $c.sbm.executeDynamic(sbmOptions5);
