/**
 * @method
 * @name schMyDept
 * @description 선택한 부서코드를 부서/팀 목록(mdsDepLst)에서 찾아 해당 행에 포커스한다.
 * @param {Number} tp 1:상위부서 목록 2:히스토리
 * @param {Number} row 선택한 행 인덱스
 * @returns {void}
 * @hidden N
 * @example scwin.schMyDept(1, row);
 */
scwin.schMyDept = function(tp, row) {
    let vDept = '';
    if (tp === 1) {
        vDept = mdsPdept.getCellData(row, "DEP_CD");
    } else {
        vDept = mdsDepHist.getCellData(row, "DEP_CD");
    }
    let tmpVal1;
    for (let i = 0; i <= mdsDepLst.getRowCount(); i++) {
        tmpVal1 = mdsDepLst.getCellData(i, "DEP_CD");
        if (tmpVal1 === vDept) {
            mdsDepLst.setFocusedCell(i, 0);
        }
    }
};

