/**
 * @method
 * @name doDepSave
 * @description 값 검증(valueCheck)·저장 데이터 세팅(setSaveDeptInfo)·모드별 확인(logicNdeptCheck)을 거쳐 부서 정보 저장 트랜잭션(trSave)을 실행한다.
 * @returns {void}
 * @hidden N
 * @example scwin.doDepSave();
 */
scwin.doDepSave = function() {
    if (scwin.valueCheck()) {
        if (scwin.setSaveDeptInfo()) {
            if (scwin.logicNdeptCheck()) {
                const url = "/depusr.do?method=saveDeptInfo";
                const keyVal = "JSP(I:pInput=mdsDeptSave)";
                trSave.Action = url;
                trSave.KeyName = "toinb_dataid4";
                trSave.KeyValue = keyVal;

                trSave.post();
            }
        } else {
            alert('팀 정보 세팅 오류!');
        }
    }
};

/**
 * @method
 * @name doHistSave
 * @description 저장 여부 확인 후 체크된 히스토리 행을 삭제(doDeleteHist)하고 히스토리 저장 트랜잭션(trSave)을 실행한다.
 * @returns {void}
 * @hidden N
 * @example scwin.doHistSave();
 */
scwin.doHistSave = function() {
    let msg1 = "수정된 사항을 저장하시겠습니까?";
    const msg2 = "\r\n(체크된 Row는 수정과 상관 없이 삭제 됩니다.)";
    if (scwin.isHistChecked()) msg1 = msg1 + msg2;
    if (confirm(msg1)) {
        if (scwin.doDeleteHist()) {
            const url = "/depusr.do?method=saveHistInfo";
            const keyVal = "JSP(I:pInput=mdsDepHist)";
            trSave.Action = url;
            trSave.KeyName = "toinb_dataid4";
            trSave.KeyValue = keyVal;

            trSave.post();
        }
    }
};

/**
 * @method
 * @name doDeleteHist
 * @description 체크(CHK_FLAG)된 히스토리 행을 삭제한다. 순서대로 지우면 하나가 지워지면서 밑엣게 위로 올라옴. 그래서 거꾸로 지움.
 * @returns {Boolean} 삭제 처리 완료 여부(항상 true)
 * @hidden N
 * @example scwin.doDeleteHist();
 */
scwin.doDeleteHist = function() {
    for (i = mdsDepHist.getRowCount(); i >= 1; i--) {
        if (mdsDepHist.getCellData(i, "CHK_FLAG") === 1) {
            mdsDepHist.removeRow(i + 1);
        }
    }
    return true;
};

/**
 * @method
 * @name isHistChecked
 * @description 히스토리에 체크된 행이 있는지 여부를 반환한다(현재 항상 false 반환).
 * @returns {Boolean} 체크된 행 존재 여부
 * @hidden N
 * @example scwin.isHistChecked();
 */
scwin.isHistChecked = function() {
    const isChecked = false;
    return isChecked;
};

/**
 * @method
 * @name logicNdeptCheck
 * @description 기능 모드(logicTp: 0:신규, 1:수정, 2:삭제)별 확인 메시지를 표시하고 진행 여부를 반환한다.
 * @returns {Boolean} 진행 여부
 * @hidden N
 * @example scwin.logicNdeptCheck();
 */
scwin.logicNdeptCheck = function() {
    if (scwin.logicTp === "0") {
        if (confirm(txtDeptNm.value + "(" + txtDeptCd.value + ")를 신규생성 하시겠습니까?")) {
            return true;
        } else return false;
    } else if (scwin.logicTp === "1") {
        const old_dep_cd = mdsDeptSave.getCellData(1, "DEP_CD");
        const new_dep_cd = mdsDeptSave.getCellData(1, "NEW_DEP_CD");
        if (old_dep_cd !== new_dep_cd) {
            if (confirm('팀코드가 변경되었습니다. 계속진행하시겠습니까?')) {

            } else {
                return false;
            }
        }
        let msg = "[" + scwin.tmpDepNm + "(" + scwin.tmpDepCd + ")]에서 [" + txtDeptNm.value + "](으)로 변경 하시겠습니까?";
        if (scwin.tmpDepNm === txtDeptNm.value) {
            msg = scwin.tmpDepNm + "(" + scwin.tmpDepCd + ") 정보를 변경 하시겠습니까?";
        }
        if (confirm(msg)) {
            return true;
        } else return false;
    } else if (scwin.logicTp === "2") {
        if (confirm(scwin.tmpDepNm + "(" + scwin.tmpDepCd + ")를 삭제 하시겠습니까?")) {
            return true;
        } else return false;
    }
};

/**
 * @method
 * @name valueCheck
 * @description 저장 전 필수값(시작일/종료일, 팀코드·팀명)을 검증한다.
 * @returns {Boolean} 검증 통과 여부
 * @hidden N
 * @example scwin.valueCheck();
 */
scwin.valueCheck = function() {
    if (meAskDate.Text === "") {
        alert("[시작일/종료일]은 필수입니다.");
        return false;
    }
    if (scwin.tmpDepCd === "" || scwin.tmpDepNm === "") {
        alert("팀코드와 팀명은 필수입니다.");
        return false;
    }
    return true;
};

/**
 * @method
 * @name setSaveDeptInfo
 * @description 입력 영역 값을 저장용 데이터셋(mdsDeptSave)에 세팅한다.
 * @returns {Boolean} 세팅 성공 여부
 * @hidden N
 * @example scwin.setSaveDeptInfo();
 */
scwin.setSaveDeptInfo = function() {
    try {
        if (mdsDeptSave.getRowCount() !== 0) {
            mdsDeptSave.setJSON([]);
        }
        mdsDeptSave.insertRow();
        mdsDeptSave.setCellData(1, "DEP_CD", scwin.tmpDepCd);
        mdsDeptSave.setCellData(1, "NEW_DEP_CD", txtDeptCd.value);
        mdsDeptSave.setCellData(1, "UP_DEP_CD", txtUpDeptCd.value);
        mdsDeptSave.setCellData(1, "DEP_NM", txtDeptNm.value);
        mdsDeptSave.setCellData(1, "CHRG_IND_NM", txtChrgIndNm.value);
        mdsDeptSave.setCellData(1, "REMK", txtRemk.Text);
        mdsDeptSave.setCellData(1, "DUTY_GRP_TP_CD", txtDutyGrpTpCd.value);
        mdsDeptSave.setCellData(1, "SNDLOC_TP_CD", txtSndlocTpCd.value);
        mdsDeptSave.setCellData(1, "KCLIC_USR_TP_ID", txtKclicUsrTpId.value);
        mdsDeptSave.setCellData(1, "ASK_DATE", meAskDate.Text);
        mdsDeptSave.setCellData(1, "LOGIC_TP", scwin.logicTp);
        return true;
    } catch (err) {
        alert(err);
        return false;
    }
};

